def findMaxValueOfEquation(points: list[list[int]], k: int) -> int:
    from collections import deque
    q = deque()
    ans = float('-inf')
    for x, y in points:
        while q and x - q[0][1] > k:
            q.popleft()
        if q:
            ans = max(ans, x + y + q[0][0])
        while q and q[-1][0] <= y - x:
            q.pop()
        q.append((y - x, x))
    return ans

